/*
 * BitBench user compressor package: one codec of the thesis benchmark.
 *
 * Generated by scripts/make_thesis_packages.py from scripts/pkg_template/;
 * the codec sources in this directory are vendored unchanged from lib/, which
 * is the implementation the firmware benchmark ran (firmware/stm32wb_mcu_bench).
 * adapter.h binds the codec to this wrapper and names the package.
 *
 * The standard int64 sequence is processed in 4096-value chunks, each mapped
 * to base + int16 offsets (the codecs code int16, as on the device). The base
 * is sticky: one global base when the whole sequence spans <= 65536 values
 * (0 when it already fits int16), otherwise the current base is kept while
 * chunks fit around it, and a new chunk-centred base restarts the codec state
 * (chunk flag bit 0). Each chunk is coded with the smaller of the codec payload
 * and an exact fallback (zig-zag LEB128 deltas or raw int64), so the container
 * never expands. For codecs whose state carries across chunks the encoder
 * snapshots it before each chunk and restores it when the fallback wins.
 *
 * Stream: magic[4] | u8 version | u8 level | u16 0 | u32 0 | u32 N, then per chunk
 *         u8 mode | u8 flags | u16 0 | i64 base | u32 len | payload
 *         mode 0 = raw int64, 1 = codec chunk, 2 = LEB128 exact fallback;
 *         flags bit 0 = start a fresh codec state before decoding.
 *
 * Input:  8-byte header (uint64 N + N x int64) or 16-byte header
 *         (uint64 N + uint64 decimals + N x int64).
 * Output: CSV row with num_values=N, uncompressed_bits=64*N; the whole stream
 *         is decoded in-process and every value checked against the bound.
 *
 * Options: the level (PKG_LEVEL_KEY: an epsilon or LSB-drop count; 0 is
 * lossless) and mode (lossy / lossless; lossless forces level 0). JSON options
 * win over flags. Unknown flags are ignored (BitBench passes its own).
 */
#define _POSIX_C_SOURCE 200809L

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "adapter.h"
#include "compact_fallback.h"

#define CHUNK 4096
#define STREAM_HDR 16
#define CHUNK_HDR 16
#define STREAM_VERSION 1
#define FLAG_RESET 1

static const char *CSV_HEADER =
    "compressor,dataset,num_values,original_size,memory_usage,"
    "uncompressed_bits,compressed_bits,compression_ratio,"
    "compression_throughput_mbs,decompression_throughput_mbs,"
    "random_access_ns,random_access_mbs,input_buffer,compressor_internal";

static size_t g_live, g_peak, g_input_bytes;
static void *x_alloc(size_t n) {
    size_t *p = malloc(n + 2 * sizeof(size_t));
    if (!p) { fputs(PKG_NAME ": out of memory\n", stderr); exit(1); }
    p[0] = n;
    g_live += n + 2 * sizeof(size_t);
    if (g_live > g_peak) g_peak = g_live;
    return (void *)(p + 2);
}
static void *x_realloc(void *ptr, size_t n) {
    if (!ptr) return x_alloc(n);
    size_t *base = (size_t *)ptr - 2;
    size_t old = base[0];
    size_t *np = realloc(base, n + 2 * sizeof(size_t));
    if (!np) { fputs(PKG_NAME ": out of memory\n", stderr); exit(1); }
    np[0] = n;
    g_live += n - old;
    if (g_live > g_peak) g_peak = g_live;
    return (void *)(np + 2);
}
static void x_free(void *ptr) {
    if (!ptr) return;
    size_t *base = (size_t *)ptr - 2;
    g_live -= base[0] + 2 * sizeof(size_t);
    free(base);
}

static double now_seconds(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

static char *read_file(const char *path, size_t *size_out) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
    long end = ftell(f);
    rewind(f);
    if (end < 0) { fclose(f); return NULL; }
    char *data = malloc((size_t)end + 1);
    if (!data) { fclose(f); return NULL; }
    size_t got = fread(data, 1, (size_t)end, f);
    fclose(f);
    data[got] = '\0';
    if (size_out) *size_out = got;
    return data;
}

static int read_bin(const char *path, int64_t **values_out, size_t *count_out,
                    uint64_t *decimals_out) {
    size_t size = 0;
    char *raw = read_file(path, &size);
    if (!raw || size < 8) { free(raw); return -1; }
    uint64_t count = 0;
    memcpy(&count, raw, 8);
    if (count > ((uint64_t)1 << 32) - 1) { free(raw); return -1; }
    size_t offset;
    if (size == 16 + (size_t)count * 8) offset = 16;
    else if (size == 8 + (size_t)count * 8) offset = 8;
    else { free(raw); return -1; }
    int64_t *values = count ? malloc((size_t)count * 8) : NULL;
    if (count && !values) { free(raw); return -1; }
    if (count) memcpy(values, raw + offset, (size_t)count * 8);
    uint64_t decimals = 0;
    if (offset == 16) memcpy(&decimals, raw + 8, 8);
    free(raw);
    *values_out = values;
    *count_out = (size_t)count;
    *decimals_out = decimals;
    return 0;
}

/* Value of a JSON string option ("key": "value"); returns its length or -1. */
static int json_string(const char *json, const char *key, const char **value) {
    const char *p = strstr(json, key);
    const char *c = p ? strchr(p, ':') : NULL;
    const char *q = c ? strchr(c, '"') : NULL;
    const char *e = q ? strchr(q + 1, '"') : NULL;
    if (!e) return -1;
    *value = q + 1;
    return (int)(e - q - 1);
}

static void apply_json_options(const char *path, int *level, int *lossless) {
    size_t size = 0;
    char *json = read_file(path, &size);
    if (!json) return;
    char *p = strstr(json, "\"" PKG_LEVEL_KEY "\"");
    if (p) { char *c = strchr(p, ':'); if (c) *level = (int)strtol(c + 1, NULL, 10); }
    const char *v;
    int n = json_string(json, "\"mode\"", &v);
    if (n == 8 && !strncmp(v, "lossless", 8)) *lossless = 1;
    else if (n == 5 && !strncmp(v, "lossy", 5)) *lossless = 0;
    free(json);
}

static void put_u32(uint8_t *p, uint32_t v) {
    p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16); p[3] = (uint8_t)(v >> 24);
}
static uint32_t get_u32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static void min_max(const int64_t *v, size_t n, int64_t *lo, int64_t *hi) {
    *lo = *hi = v[0];
    for (size_t i = 1; i < n; i++) {
        if (v[i] < *lo) *lo = v[i];
        if (v[i] > *hi) *hi = v[i];
    }
}

/* True when v - base is in [-32768, 32767] (exact for every int64 pair). */
static int in_window(int64_t v, int64_t base) {
    return v >= base ? (uint64_t)v - (uint64_t)base <= 32767u
                     : (uint64_t)base - (uint64_t)v <= 32768u;
}

/* Base for a value span [lo, hi]: 0 when it already fits int16, otherwise
 * centred. Returns 0 when the span is wider than int16 or a reconstruction
 * within `margin` of the input could leave int64. */
static int choose_base(int64_t lo, int64_t hi, int64_t margin, int64_t *base_out) {
    uint64_t range = (uint64_t)hi - (uint64_t)lo;
    if (range > 65535 || hi > INT64_MAX - margin || lo < INT64_MIN + margin)
        return 0;
    if (lo >= INT16_MIN && hi <= INT16_MAX) {
        *base_out = 0;
        return 1;
    }
    int64_t half = (int64_t)((range + 1) / 2);
    *base_out = lo <= INT64_MAX - half ? lo + half
                                       : hi - (int64_t)(range - (uint64_t)half);
    return 1;
}

int main(int argc, char **argv) {
    int level = PKG_LEVEL_DEFAULT, lossless = 0;
    const char *out_path = NULL, *in_path = NULL, *options_path = NULL;
    const char *level_flag = "--" PKG_LEVEL_KEY "=";
    size_t level_flag_len = strlen(level_flag);

    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (!strcmp(a, "-o") && i + 1 < argc) out_path = argv[++i];
        else if (!strcmp(a, "--options") && i + 1 < argc) options_path = argv[++i];
        else if (!strncmp(a, level_flag, level_flag_len))
            level = (int)strtol(a + level_flag_len, NULL, 10);
        else if (!strncmp(a, "--mode=", 7)) lossless = !strcmp(a + 7, "lossless");
        else if (a[0] != '-') in_path = a;
    }
    if (options_path) apply_json_options(options_path, &level, &lossless);
    if (lossless) level = 0;
    if (level < 0 || level > PKG_LEVEL_MAX) {
        fprintf(stderr, PKG_NAME ": " PKG_LEVEL_KEY " must be 0..%d\n", PKG_LEVEL_MAX);
        return 1;
    }
    if (!out_path || !in_path) {
        fprintf(stderr, "usage: codec -o <out.csv> [--" PKG_LEVEL_KEY "=%d] "
                "[--mode=lossy|lossless] [--options <json>] <input.bin>\n",
                PKG_LEVEL_DEFAULT);
        return 1;
    }

    int64_t *values = NULL;
    size_t count = 0;
    uint64_t decimals = 0;
    if (read_bin(in_path, &values, &count, &decimals) != 0) {
        fprintf(stderr, PKG_NAME ": cannot read input %s\n", in_path);
        return 1;
    }
    g_input_bytes = count * 8;
    size_t nchunks = count ? (count + CHUNK - 1) / CHUNK : 0;
    const uint64_t bound = ad_bound(level);

    ad_state *enc = x_alloc(sizeof *enc);
    ad_state *enc_saved = x_alloc(sizeof *enc_saved);
    if (ad_init(enc, level) != 0) {
        fputs(PKG_NAME ": codec init failed\n", stderr);
        return 1;
    }
    int16_t *offs = x_alloc(CHUNK * 2);
    int32_t *recon = x_alloc(CHUNK * 4);
    int64_t *exact = x_alloc(CHUNK * 8);
    size_t chunk_cap = ad_max_bytes(CHUNK);
    uint8_t *chunk = x_alloc(chunk_cap);
    uint8_t *fbuf = x_alloc(CHUNK * 9 + 16);
    size_t out_cap = 1 << 16;
    uint8_t *out = x_alloc(out_cap);
    size_t used = 0;

    double t0 = now_seconds();
    memcpy(out, PKG_MAGIC, 4);
    out[4] = STREAM_VERSION;
    out[5] = (uint8_t)level;
    out[6] = out[7] = 0;
    put_u32(out + 8, 0);
    put_u32(out + 12, (uint32_t)count);
    used = STREAM_HDR;

    int64_t base = 0, lo, hi;
    int have_base = 0;
    if (count) {
        min_max(values, count, &lo, &hi);
        have_base = choose_base(lo, hi, (int64_t)bound, &base);
    }
    int coded_before = 0;
    for (size_t c = 0; c < nchunks; c++) {
        size_t off = c * CHUNK;
        size_t cn = count - off < CHUNK ? count - off : CHUNK;
        min_max(values + off, cn, &lo, &hi);
        int64_t chunk_base = base;
        int fits = have_base && in_window(lo, base) && in_window(hi, base) &&
                   hi <= INT64_MAX - (int64_t)bound && lo >= INT64_MIN + (int64_t)bound;
        int reset = !coded_before;
        if (!fits && choose_base(lo, hi, (int64_t)bound, &chunk_base)) {
            fits = 1;
            reset = 1;
        }
        size_t z = 0;
        if (fits) {
            if (PKG_STATEFUL)
                *enc_saved = *enc;
            if (reset && ad_init(enc, level) != 0) {
                fputs(PKG_NAME ": codec init failed\n", stderr);
                return 1;
            }
            for (size_t i = 0; i < cn; i++)
                offs[i] = (int16_t)(values[off + i] - chunk_base);
            z = ad_encode(enc, offs, cn, chunk, chunk_cap);
        }
        int varint = 0;
        size_t fb_size = cf_best_size(values + off, cn, &varint);
        int mode;
        if (fits && z > 0 && z <= fb_size) {
            mode = 1;
            base = chunk_base;
            have_base = 1;
            coded_before = 1;
        } else {
            mode = varint ? 2 : 0;
            if (fits && PKG_STATEFUL)          /* undo the rejected chunk */
                *enc = *enc_saved;
        }
        size_t payload = mode == 1 ? z : fb_size;
        size_t need = CHUNK_HDR + payload;
        if (used + need > out_cap) {
            while (used + need > out_cap) out_cap *= 2;
            out = x_realloc(out, out_cap);
        }
        int64_t frame_base = mode == 1 ? chunk_base : 0;
        out[used++] = (uint8_t)mode;
        out[used++] = (uint8_t)(mode == 1 && reset ? FLAG_RESET : 0);
        out[used++] = 0; out[used++] = 0;
        memcpy(out + used, &frame_base, 8); used += 8;
        put_u32(out + used, (uint32_t)payload); used += 4;
        if (mode == 1) {
            memcpy(out + used, chunk, z); used += z;
        } else if (mode == 2) {
            size_t got = cf_varint_encode(values + off, cn, fbuf, fb_size);
            if (got != fb_size) { fputs(PKG_NAME ": fallback encode failed\n", stderr); return 1; }
            memcpy(out + used, fbuf, fb_size); used += fb_size;
        } else {
            memcpy(out + used, values + off, fb_size); used += fb_size;
        }
    }
    double t_comp = now_seconds();
    { const char *dp = getenv("DUMP_STREAM");
      if (dp) { FILE *df = fopen(dp, "wb");
                if (df) { fwrite(out, 1, used, df); fclose(df); } } }

    /* decode + verify */
    if (used < STREAM_HDR || memcmp(out, PKG_MAGIC, 4) != 0 ||
        out[4] != STREAM_VERSION || out[5] != (uint8_t)level ||
        get_u32(out + 12) != (uint32_t)count) {
        fputs(PKG_NAME ": bad stream header\n", stderr);
        return 1;
    }
    ad_state *dec = x_alloc(sizeof *dec);
    int dec_ready = 0;
    int64_t dec_base = 0;
    size_t pos = STREAM_HDR;
    size_t coded_chunks = 0, resets = 0;
    uint64_t max_err = 0;
    long double sum_err = 0;
    double t_dec = 0;
    for (size_t c = 0; c < nchunks; c++) {
        if (pos + CHUNK_HDR > used) goto truncated;
        int mode = out[pos];
        int flags = out[pos + 1];
        int64_t cb;
        memcpy(&cb, out + pos + 4, 8);
        uint32_t len = get_u32(out + pos + 12);
        pos += CHUNK_HDR;
        if (len > used - pos) goto truncated;
        size_t off = c * CHUNK;
        size_t cn = count - off < CHUNK ? count - off : CHUNK;
        double d0 = now_seconds();
        if (mode == 0) {
            if (len != cn * 8) goto truncated;
            for (size_t i = 0; i < cn; i++) {
                int64_t v;
                memcpy(&v, out + pos + i * 8, 8);
                if (v != values[off + i]) {
                    fprintf(stderr, PKG_NAME ": raw mismatch at %zu\n", off + i);
                    return 1;
                }
            }
        } else if (mode == 2) {
            if (cf_varint_decode(out + pos, len, exact, cn) != 0)
                goto truncated;
            for (size_t i = 0; i < cn; i++)
                if (exact[i] != values[off + i]) {
                    fprintf(stderr, PKG_NAME ": fallback mismatch at %zu\n", off + i);
                    return 1;
                }
        } else if (mode == 1) {
            if (flags & FLAG_RESET) {
                if (ad_init(dec, level) != 0) {
                    fputs(PKG_NAME ": codec init failed\n", stderr);
                    return 1;
                }
                dec_ready = 1;
                dec_base = cb;
                resets++;
            } else if (!dec_ready || cb != dec_base) {
                fputs(PKG_NAME ": coded chunk without a state reset\n", stderr);
                return 1;
            }
            if (ad_decode(dec, out + pos, len, recon, cn) != 0) {
                fputs(PKG_NAME ": decode failed\n", stderr);
                return 1;
            }
            for (size_t i = 0; i < cn; i++) {
                int64_t e = values[off + i] - ((int64_t)recon[i] + cb);
                uint64_t ae = (uint64_t)(e < 0 ? -e : e);
                if (ae > bound) {
                    fprintf(stderr, PKG_NAME ": bound violated at %zu (%" PRIu64
                            " > %" PRIu64 ")\n", off + i, ae, bound);
                    return 1;
                }
                if (ae > max_err) max_err = ae;
                sum_err += ae;
            }
            coded_chunks++;
        } else {
            fputs(PKG_NAME ": bad chunk mode\n", stderr);
            return 1;
        }
        t_dec += now_seconds() - d0;
        pos += len;
    }
    if (pos != used) goto truncated;

    fprintf(stderr, PKG_NAME ": %zu values, %zu chunks (4096), %zu codec-coded, "
            "%zu state reset(s), " PKG_LEVEL_KEY "=%d (bound %" PRIu64 "), max error %"
            PRIu64 " LSB, mean %.4Lf LSB\n", count, nchunks, coded_chunks, resets,
            level, bound, max_err, count ? sum_err / (long double)count : 0.0L);
    fprintf(stderr, PKG_NAME ": memory: compressor peak %zu B (codec state %zu B), "
            "input array %zu B, total %zu B\n", g_peak, sizeof(ad_state),
            g_input_bytes, g_peak + g_input_bytes);
    if (decimals)
        fprintf(stderr, PKG_NAME ": input decimals field = %" PRIu64 "\n", decimals);

    size_t original_size = count * 8;
    size_t uncompressed_bits = count * 64;
    size_t compressed_bits = used * 8;
    double ratio = uncompressed_bits
        ? (double)compressed_bits / (double)uncompressed_bits : 0.0;
    double comp_mbs = t_comp > t0
        ? ((double)original_size / 1048576.0) / (t_comp - t0) : 0.0;
    double decomp_mbs = t_dec > 0
        ? ((double)original_size / 1048576.0) / t_dec : 0.0;
    FILE *out_csv = fopen(out_path, "w");
    if (!out_csv) { fprintf(stderr, PKG_NAME ": cannot write %s\n", out_path); return 1; }
    fprintf(out_csv, "%s\n", CSV_HEADER);
    fprintf(out_csv, "%s,bitbench,%zu,%zu,%zu,%zu,%zu,%.6f,%.3f,%.3f,,,%zu,%zu\n",
            PKG_NAME, count, original_size, g_peak + g_input_bytes, uncompressed_bits,
            compressed_bits, ratio, comp_mbs, decomp_mbs, g_input_bytes, g_peak);
    fclose(out_csv);

    x_free(dec); x_free(out); x_free(fbuf); x_free(chunk); x_free(exact);
    x_free(recon); x_free(offs); x_free(enc_saved); x_free(enc);
    free(values);
    return 0;

truncated:
    fputs(PKG_NAME ": truncated compressed stream\n", stderr);
    return 1;
}
